/* MD Converter service worker — generated by scripts/build.mjs. Do not edit. */

const CACHE_NAME = '__CACHE_NAME__';
const SHARE_CACHE = 'md-converter-share';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // Cache entries one by one: a single 404 must not void the whole install.
      await Promise.all(
        PRECACHE.map(async (url) => {
          try {
            const response = await fetch(new Request(url, { cache: 'reload' }));
            if (response.ok) await cache.put(url, response);
          } catch (error) {
            /* offline during install; the runtime handler will fill the gap */
          }
        })
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name !== CACHE_NAME && name !== SHARE_CACHE).map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);

  if (request.method === 'POST' && url.pathname.endsWith('/share-target')) {
    event.respondWith(handleShare(event));
    return;
  }

  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigation(request));
    return;
  }

  event.respondWith(cacheFirst(request));
});

async function handleNavigation(request) {
  const cache = await caches.open(CACHE_NAME);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put('./index.html', response.clone());
    return response;
  } catch (error) {
    const cached = (await cache.match('./index.html')) || (await cache.match('./'));
    if (cached) return cached;
    throw error;
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request, { ignoreSearch: true });
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok && response.type === 'basic') cache.put(request, response.clone());
  return response;
}

/** Web Share Target: park the shared files, then hand control to the page. */
async function handleShare(event) {
  try {
    const formData = await event.request.formData();
    const cache = await caches.open(SHARE_CACHE);
    const files = formData.getAll('files');
    let index = 0;

    for (const file of files) {
      if (!(file instanceof File)) continue;
      const name = file.name || `shared-${++index}`;
      await cache.put(
        new Request(`./shared/${encodeURIComponent(name)}`),
        new Response(file, { headers: { 'Content-Type': file.type || 'application/octet-stream' } })
      );
    }

    const text = formData.get('text');
    if (typeof text === 'string' && text.trim()) {
      await cache.put(
        new Request('./shared/shared-text.txt'),
        new Response(text, { headers: { 'Content-Type': 'text/plain' } })
      );
    }
  } catch (error) {
    /* fall through to the redirect so the user still lands in the app */
  }
  return Response.redirect('./?share-target=1', 303);
}
